import { useEffect, useRef, useState } from 'react'
import { api, bootstrapSession, exportComparison, exportSortSelection, upload, uploadAsset, uploadComparison, uploadFiles, type ApiRecord } from './api/client'
import './App.css'

type Navigate = (view: string) => void
type Action = (work: () => Promise<unknown>, message: string) => void

const primaryNav = [['dashboard', 'Home'], ['sort', 'Sort email'], ['compare', 'Compare lists'], ['send', 'Send'], ['history', 'History']]
const utilityNav = [['accounts', 'Email accounts'], ['saved', 'Saved lists'], ['settings', 'Settings']]
const pageMeta: Record<string, { label: string, description: string }> = {
  dashboard: { label: 'Home', description: 'Choose a task and keep the important local status in view.' },
  sort: { label: 'Sort email', description: 'Clean, classify, and export addresses without an account or a send.' },
  compare: { label: 'Compare lists', description: 'Find overlap, new addresses, and previous successful submissions.' },
  send: { label: 'Send', description: 'Prepare one clear email operation from a file, pasted addresses, or a saved result.' },
  history: { label: 'History', description: 'Review what was prepared, submitted, deferred, canceled, or left uncertain.' },
  accounts: { label: 'Email accounts', description: 'Save a sender account locally when you are ready to send.' },
  saved: { label: 'Saved lists', description: 'Keep useful recipient lists available without building a contact database first.' },
  settings: { label: 'Settings', description: 'Local storage, backups, and advanced compatibility information.' },
}

function viewFromPath(pathname: string) {
  const segment = pathname.replace(/^\/+/, '').split('/')[0]
  return pageMeta[segment] ? segment : 'dashboard'
}
function apiPath(view: string) { return ({ dashboard: '/dashboard', sort: '/list-tools/jobs', compare: '/list-comparison/history', send: '/campaigns', history: '/campaigns', accounts: '/providers', saved: '/lists', settings: '/runtime' } as Record<string, string>)[view] || '/dashboard' }

function App() {
  const [view, setView] = useState(() => viewFromPath(window.location.pathname)); const [data, setData] = useState<ApiRecord>({}); const [setup, setSetup] = useState<ApiRecord>({}); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [initialLoading, setInitialLoading] = useState(true); const [pageUnavailable, setPageUnavailable] = useState(false); const [mobileOpen, setMobileOpen] = useState(false); const [utilityOpen, setUtilityOpen] = useState(() => utilityNav.some(([id]) => id === view)); const menuButton = useRef<HTMLButtonElement>(null); const navRef = useRef<HTMLElement>(null); const initialView = useRef(view)
  const load = async (target = view) => { setBusy(true); setError(''); try { setData(await api<ApiRecord>(apiPath(target))) } catch (err) { setError(err instanceof Error ? err.message : 'Unable to load this page') } finally { setBusy(false) } }
  const navigate: Navigate = target => { const [targetView, query = ''] = target.split('?'); const next = targetView === 'dashboard' ? '/' : `/${targetView}${query ? `?${query}` : ''}`; if (window.location.pathname + window.location.search !== next) window.history.pushState({}, '', next); setView(targetView); setMobileOpen(false); if (utilityNav.some(([id]) => id === targetView)) setUtilityOpen(true); void load(targetView) }
  const run: Action = (work, message) => { setBusy(true); setError(''); void work().then(() => { setNotice(message); return load(viewFromPath(window.location.pathname)) }).catch(err => setError(err instanceof Error ? err.message : 'Action failed')).finally(() => setBusy(false)) }
  useEffect(() => { const pop = () => { const next = viewFromPath(window.location.pathname); setView(next); void load(next) }; window.addEventListener('popstate', pop); bootstrapSession().then(async () => { setSetup(await api('/setup')); await load(initialView.current) }).catch(err => { setPageUnavailable(true); setError(err.message) }).finally(() => setInitialLoading(false)); return () => window.removeEventListener('popstate', pop) }, [])
  useEffect(() => { if (!mobileOpen) return; const previous = document.body.style.overflow; document.body.style.overflow = 'hidden'; const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') { setMobileOpen(false); menuButton.current?.focus() }; if (event.key === 'Tab') { const controls = Array.from(navRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href]') || []); if (!controls.length) return; if (event.shiftKey && document.activeElement === controls[0]) { event.preventDefault(); controls.at(-1)?.focus() }; if (!event.shiftKey && document.activeElement === controls.at(-1)) { event.preventDefault(); controls[0]?.focus() } } }; document.addEventListener('keydown', onKey); requestAnimationFrame(() => navRef.current?.querySelector<HTMLButtonElement>('button')?.focus()); return () => { document.body.style.overflow = previous; document.removeEventListener('keydown', onKey) } }, [mobileOpen])
  const meta = pageMeta[view] || pageMeta.dashboard
  const content = view === 'dashboard' ? <Home data={data} setup={setup} onSetup={() => run(async () => { const result = await api('/setup/complete', { method: 'POST', body: JSON.stringify({ timezone: 'UTC', simulation_mode: true, sample_data: false }) }); setSetup(result); return result }, 'Local workspace ready')} onNavigate={navigate} /> : view === 'sort' ? <Sorter data={data} onRun={run} onNavigate={navigate} /> : view === 'compare' ? <CompareLists data={data} onRun={run} onNavigate={navigate} /> : view === 'send' ? <Sender data={data} onRun={run} /> : view === 'history' ? <History data={data} onNavigate={navigate} /> : view === 'accounts' ? <Accounts data={data} onRun={run} /> : view === 'saved' ? <SavedLists data={data} onNavigate={navigate} /> : <Settings data={data} />
  return <div className="shell"><aside ref={navRef} className={`rail ${mobileOpen ? 'mobile-open' : ''}`} aria-label="Mailforge navigation"><div className="brand"><button className="brand-button" onClick={() => navigate('dashboard')}><span className="brand-mark">M</span><span>Mailforge</span></button></div><p className="rail-kicker">LOCAL EMAIL UTILITY</p><nav className="nav-section" aria-label="Main navigation"><p className="nav-label">Work</p>{primaryNav.map(([id, label]) => <button key={id} className={view === id ? 'nav-item active' : 'nav-item'} aria-current={view === id ? 'page' : undefined} onClick={() => navigate(id)}>{label}</button>)}</nav><nav className="nav-section utility-section" aria-label="Utility navigation"><button className="utility-toggle" aria-expanded={utilityOpen} onClick={() => setUtilityOpen(open => !open)}>More tools <span aria-hidden="true">{utilityOpen ? '−' : '+'}</span></button>{utilityOpen && utilityNav.map(([id, label]) => <button key={id} className={view === id ? 'nav-item active' : 'nav-item'} aria-current={view === id ? 'page' : undefined} onClick={() => navigate(id)}>{label}</button>)}</nav><div className="rail-foot"><span className="live-dot" /> Local only<small>Simulation and controlled execution</small></div></aside><main className="main" aria-busy={initialLoading}><header className="topbar"><div className="topbar-heading"><button ref={menuButton} className="mobile-menu-button" aria-label={mobileOpen ? 'Close navigation' : 'Open navigation'} aria-expanded={mobileOpen} onClick={() => setMobileOpen(open => !open)}>☰</button><div><p className="eyebrow">MAILFORGE / LOCAL</p><h1>{meta.label}</h1><p className="page-description">{meta.description}</p></div></div><div className="top-actions"><span className="status-chip"><span className="live-dot" /> Local only</span><button className="icon-button" aria-label="Refresh this page" onClick={() => void load()}>↻</button></div></header>{initialLoading && <div className="initial-loading-panel" role="status">Loading {meta.label}…</div>}{mobileOpen && <button className="nav-scrim" aria-label="Close navigation" onClick={() => { setMobileOpen(false); menuButton.current?.focus() }} />}{notice && <div className="notice" role="status">{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notification">×</button></div>}{error && <div className="error" role="alert"><span>{error}</span><button onClick={() => void load()}>Retry</button><button onClick={() => setError('')} aria-label="Dismiss error">×</button></div>}{busy && !initialLoading && <div className="loading" role="status">Updating local state…</div>}{!initialLoading && (pageUnavailable ? <Unavailable onRetry={() => void load()} /> : content)}</main></div>
}

function Home({ data, setup, onSetup, onNavigate }: { data: ApiRecord, setup: ApiRecord, onSetup: () => void, onNavigate: Navigate }) { const counts = data.counts || {}; return <div className="content home-content"><section className="home-intro"><div><p className="eyebrow teal">A SIMPLE EMAIL TOOLKIT</p><h2>Work with lists and send when you are ready.</h2><p className="lede">Sort addresses, compare files, or prepare one direct email operation. You do not need an account, campaign, or contact database to begin.</p></div><div className="local-note"><strong>Private by default</strong><span>Files and history stay in this local workspace.</span></div></section><section aria-labelledby="tasks-title"><div className="section-head"><div><p className="eyebrow">START WITH A TASK</p><h3 id="tasks-title">Choose what you need to do</h3></div></div><div className="task-grid task-grid-three"><TaskCard number="01" title="Sort email" text="Clean, classify by provider and domain, remove duplicates, and export useful groups." action="Open sorter" onClick={() => onNavigate('sort')} tone="teal" /><TaskCard number="02" title="Compare lists" text="Find overlap, new addresses, unique groups, or people successfully contacted before." action="Compare files" onClick={() => onNavigate('compare')} /><TaskCard number="03" title="Send" text="Paste addresses or use a file, add plain text or HTML, preview the scope, and send or schedule." action="Prepare a send" onClick={() => onNavigate('send')} /></div></section>{!setup.complete && <section className="home-callout"><div><p className="eyebrow teal">OPTIONAL SETUP</p><h3>Save workspace preferences</h3><p>You can use the sorter and comparison tools immediately. Set up the local workspace only when you want saved preferences and recovery tools.</p></div><button className="primary" onClick={onSetup}>Finish local setup</button></section>}<section className="home-status"><div className="section-head"><div><p className="eyebrow">LOCAL STATUS</p><h3>Useful context, not a dashboard</h3></div><button className="text-button" onClick={() => onNavigate('history')}>Open history →</button></div><div className="stat-grid compact-stat-grid"><Stat label="Saved recipients" value={counts.contacts ?? 0} tone="teal" /><Stat label="Saved lists" value={counts.lists ?? 0} /><Stat label="Recent sends" value={data.campaigns?.length ?? 0} /></div></section></div> }
function TaskCard({ number, title, text, action, onClick, tone = '' }: { number: string, title: string, text: string, action: string, onClick: () => void, tone?: string }) { return <article className={`task-card ${tone}`}><span className="task-number">{number}</span><h3>{title}</h3><p>{text}</p><button className="text-button" onClick={onClick}>{action} <span aria-hidden="true">→</span></button></article> }
function Stat({ label, value, tone = '' }: { label: string, value: string | number, tone?: string }) { return <div className={`stat-card ${tone}`}><span>{label}</span><strong>{value}</strong><small>local workspace</small></div> }
function Empty({ text }: { text: string }) { return <div className="empty"><span aria-hidden="true">○</span><p>{text}</p></div> }
function Unavailable({ onRetry }: { onRetry: () => void }) { return <div className="content"><section className="panel" role="alert"><p className="eyebrow amber">LOCAL SERVICE UNAVAILABLE</p><h2>Mailforge could not load this page</h2><p className="muted">The local service did not return the requested data. No empty-state result is being shown. Check that Mailforge is running, then retry the connection.</p><button className="primary" onClick={onRetry}>Retry connection</button></section></div> }
function PageIntro({ eyebrow, title, text, badge }: { eyebrow: string, title: string, text: string, badge: string }) { const handoff = new URLSearchParams(window.location.search).get('list_id'); return <div className="toolbar"><div><p className="eyebrow teal">{eyebrow}</p><h2>{title}</h2><p className="muted">{handoff && (eyebrow === 'LIST COMPARISON' || eyebrow === 'EMAIL SENDER') ? 'Using the selected sorted result from this local workspace.' : text}</p></div><span className="status-chip">{badge}</span></div> }

function Sorter({ data, onRun, onNavigate }: { data: ApiRecord, onRun: Action, onNavigate: Navigate }) {
  const [file, setFile] = useState<File | null>(null); const [profile, setProfile] = useState('full'); const [dnsMode, setDnsMode] = useState('offline'); const [preview, setPreview] = useState<ApiRecord | null>(null); const [job, setJob] = useState<ApiRecord | null>(null); const [selectedProviders, setSelectedProviders] = useState<string[]>([]); const [selectionMode, setSelectionMode] = useState<'all' | 'selected' | 'none'>('all'); const jobs: ApiRecord[] = data.items || []
  const refresh = async (id: string) => setJob(await api<ApiRecord>(`/list-tools/jobs/${id}`))
  useEffect(() => { if (!job || ['completed', 'failed', 'canceled', 'paused'].includes(job.status)) return; const timer = window.setInterval(() => void refresh(job.id), 750); return () => window.clearInterval(timer) }, [job])
  const inspect = () => file && onRun(async () => { const result = await upload('/list-tools/preview', file); setPreview(result); return result }, 'Preview ready; the original file was not changed')
  const start = () => file && onRun(async () => { const created = await upload('/list-tools/jobs', file, `?profile=${profile}&dns_mode=${dnsMode}`); await api(`/list-tools/jobs/${created.id}/start`, { method: 'POST' }); await refresh(created.id); return created }, 'Email sorting started')
  const groups = job?.summary?.providers || {}
  const toggleProvider = (provider: string) => { if (selectionMode === 'all') { setSelectionMode('selected'); setSelectedProviders(providerNames.filter(item => item !== provider)); return } const next = selectedProviders.includes(provider) ? selectedProviders.filter(item => item !== provider) : [...selectedProviders, provider]; setSelectedProviders(next); setSelectionMode(next.length === 0 ? 'none' : next.length === providerNames.length ? 'all' : 'selected') }
  const handoff = (destination: string) => job && onRun(async () => { const result = await api<ApiRecord>(`/list-tools/jobs/${job.id}/handoff`, { method: 'POST', body: JSON.stringify({ provider_keys: selectedProviders, selection_mode: selectionMode }) }); onNavigate(`${destination}?list_id=${encodeURIComponent(result.list?.id)}`); return result }, selectionMode === 'none' ? 'No providers selected; empty result transferred' : selectionMode === 'all' ? (destination === 'compare' ? 'All sorted providers ready to compare' : 'All sorted providers ready to send') : (destination === 'compare' ? 'Selected sorted result ready to compare' : 'Selected sorted result ready to send'))
  const exportSelected = () => job && onRun(async () => { const blob = await exportSortSelection(job.id, selectedProviders, selectionMode); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'mailforge-sorted-selection.csv'; link.click(); URL.revokeObjectURL(url) }, selectionMode === 'none' ? 'No providers selected; empty export created' : selectionMode === 'all' ? 'All sorted rows exported with associated data' : 'Selected sorted rows exported with associated data')
  const providerNames = Object.keys(groups)
  return <div className="content"><PageIntro eyebrow="EMAIL SORTER" title="Sort and understand an address list" text="Import a file, inspect the consequences, then select the classified providers you want to carry into comparison or sending. Sorting never creates contacts or sends email." badge="No account needed" /><section className="panel"><div className="panel-head"><div><h3>Choose an input</h3><p className="muted">TXT, CSV, JSON, and JSONL are supported. The original stays intact.</p></div></div><label className="file-drop">{file ? file.name : 'Choose an address file'}<input aria-label="Email sorter input file" type="file" accept=".txt,.csv,.json,.jsonl" onChange={event => setFile(event.target.files?.[0] || null)} /></label><div className="inline-fields"><label>Processing profile<select value={profile} onChange={event => setProfile(event.target.value)}><option value="full">Full classification</option><option value="validation">Validation only</option><option value="dedupe">Duplicates and validity</option><option value="classify">Provider and domain groups</option></select></label><label>Mail-host lookup<select value={dnsMode} onChange={event => setDnsMode(event.target.value)}><option value="offline">Visible domain only</option><option value="sync">Resolve mail hosts</option></select></label><div className="button-row"><button disabled={!file} onClick={inspect}>Preview</button><button className="primary" disabled={!file} onClick={start}>Sort this file</button></div></div>{preview && <div className="stat-grid"><Stat label="Accepted" value={preview.accepted} tone="teal" /><Stat label="Invalid" value={preview.invalid} tone="amber" /><Stat label="Duplicates" value={preview.duplicates} /></div>}</section>{job && <section className="panel"><div className="panel-head"><div><h3>{job.source_filename}</h3><p className="muted">{job.status} · {job.processed_count || 0} records examined · {job.accepted_count || 0} accepted</p></div><span className={`status ${job.status}`}>{job.status}</span></div>{job.summary?.counts && <div className="stat-grid"><Stat label="Invalid" value={job.summary.counts.invalid ?? 0} tone="amber" /><Stat label="Duplicates removed" value={job.summary.counts.duplicates_removed ?? 0} /><Stat label="Unknown provider" value={job.summary.counts.unknown ?? 0} /></div>}<div className="provider-groups"><div className="panel-head"><div><h4>Visible email-domain providers</h4><p className="muted">Select one, several, or all providers. Unknown/custom classifications remain available for selection.</p></div><button onClick={() => { setSelectionMode('all'); setSelectedProviders(providerNames) }}>{selectionMode === 'all' ? 'All providers selected' : 'Select all providers'}</button></div><div className="group-list">{providerNames.map(name => <label className="check-row" key={name}><input type="checkbox" checked={selectionMode === 'all' || selectedProviders.includes(name)} onChange={() => toggleProvider(name)} /><span><strong>{name}</strong><small>{String(groups[name])} accepted</small></span></label>)}</div>{Object.keys(job.summary?.hosting || {}).length > 0 ? <><h4>Resolved mail-host providers</h4><div className="group-list">{Object.entries(job.summary.hosting).map(([name, count]) => <span className="group-chip" key={name}><strong>{name}</strong> {String(count)}</span>)}</div></> : <p className="muted">Mail-host classification was not established for this run; choose “Resolve mail hosts” for a bounded DNS pass.</p>}</div><p className="muted">{selectionMode === 'all' ? 'All providers are selected.' : selectionMode === 'none' ? 'No providers are selected. Transfers and exports will contain zero rows.' : `${selectedProviders.length} provider${selectedProviders.length === 1 ? '' : 's'} selected.`}</p><div className="button-row">{job.status === 'completed' && <><button onClick={() => handoff('compare')}>Compare this result</button><button onClick={() => handoff('send')}>Send this result</button><button onClick={exportSelected}>Export selected</button></>}{job.status === 'running' && <button onClick={() => onRun(() => api(`/list-tools/jobs/${job.id}/pause`, { method: 'POST' }), 'Sorting paused')}>Pause</button>}{job.status === 'paused' && <button onClick={() => onRun(() => api(`/list-tools/jobs/${job.id}/resume`, { method: 'POST' }), 'Sorting resumed')}>Resume</button>}</div>{job.artifacts?.length ? <div className="list-stack">{job.artifacts.map((artifact: ApiRecord) => <a className="list-row" key={artifact.id} href={`/api/v1/list-tools/jobs/${job.id}/artifacts/${artifact.id}`}><span><strong>{artifact.filename}</strong><small>{artifact.kind} · {artifact.size_bytes} bytes</small></span><b>Download ↓</b></a>)}</div> : <p className="muted">Exports appear when sorting completes.</p>}</section>}<section className="panel table-panel"><div className="panel-head"><h3>Recent sorting</h3><span className="muted">Durable local history</span></div>{jobs.length ? <table><thead><tr><th>Input</th><th>Status</th><th>Accepted</th><th>Updated</th></tr></thead><tbody>{jobs.map(item => <tr key={item.id} tabIndex={0} onClick={() => { setSelectionMode('all'); setSelectedProviders([]); void refresh(item.id) }} onKeyDown={event => event.key === 'Enter' && void refresh(item.id)}><td><strong>{item.source_filename}</strong><small className="table-subline">{item.profile}</small></td><td>{item.status}</td><td>{item.accepted_count}</td><td>{new Date(item.updated_at).toLocaleString()}</td></tr>)}</tbody></table> : <Empty text="No sorted lists yet." />}</section></div>
}

function CompareLists({ data, onRun, onNavigate }: { data: ApiRecord, onRun: Action, onNavigate: Navigate }) {
  const [main, setMain] = useState<File | null>(null)
  const [references, setReferences] = useState<File[]>([])
  const [operation, setOperation] = useState('subtract')
  const [result, setResult] = useState<ApiRecord | null>(null)
  const [lists, setLists] = useState<ApiRecord[]>([])
  const [mainList, setMainList] = useState(() => new URLSearchParams(window.location.search).get('list_id') || '')
  const [referenceLists, setReferenceLists] = useState<string[]>([])
  const [history, setHistory] = useState<string[]>([])
  useEffect(() => { void api<ApiRecord>('/lists').then(value => setLists(value.items || [])) }, [])
  const historyItems: ApiRecord[] = data.items || []
  const compare = () => onRun(async () => { const value = await uploadComparison(main, references, { operation, campaign_ids: JSON.stringify(history), main_list_id: mainList, reference_list_ids: JSON.stringify(referenceLists) }); setResult(value); return value }, 'Comparison calculated without changing either list')
  const download = () => result && onRun(async () => { const blob = await exportComparison(result); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'mailforge-comparison.csv'; link.click(); URL.revokeObjectURL(url) }, 'Comparison exported')
  const sendResult = () => result && onRun(async () => { const handoff = await api<ApiRecord>('/list-comparison/handoff', { method: 'POST', body: JSON.stringify({ results: result.results }) }); onNavigate(`send?list_id=${encodeURIComponent(handoff.list.id)}`); return handoff }, 'Comparison result ready to send')
  return <div className="content"><PageIntro eyebrow="LIST COMPARISON" title="Find what is new, shared, or already sent" text="Compare files, saved lists, or selected successful submission history. Prepared, queued, canceled, and uncertain attempts are not counted as sent." badge="Read-only" /><section className="split"><section className="panel"><h3>Main list</h3><p className="muted">Use a file or a saved list.</p><label>Saved list<select value={mainList} onChange={event => setMainList(event.target.value)}><option value="">Upload a file instead</option>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label>{!mainList && <label className="file-drop">{main?.name || 'Choose the main list'}<input aria-label="Main comparison list" type="file" accept=".txt,.csv,.json,.jsonl" onChange={event => setMain(event.target.files?.[0] || null)} /></label>}</section><section className="panel"><h3>Reference lists</h3><p className="muted">Add files or choose saved lists to compare against.</p><label className="file-drop">{references.length ? `${references.length} file${references.length === 1 ? '' : 's'} selected` : 'Choose reference files'}<input aria-label="Reference comparison lists" multiple type="file" accept=".txt,.csv,.json,.jsonl" onChange={event => setReferences(Array.from(event.target.files || []))} /></label><label>Saved lists<select multiple value={referenceLists} onChange={event => setReferenceLists(Array.from(event.target.selectedOptions, option => option.value))}>{lists.map(list => <option key={list.id} value={list.id}>{list.name}</option>)}</select></label></section></section><section className="panel"><div className="inline-fields"><label>What to calculate<select value={operation} onChange={event => setOperation(event.target.value)}><option value="subtract">Only in the main list</option><option value="intersection">In both selections</option><option value="union">Merge unique addresses</option><option value="unique_main">Unique to the main list</option><option value="duplicates">Duplicates in the main list</option></select></label><button className="primary" onClick={compare} disabled={!main && !mainList}>Compare lists</button></div><fieldset className="history-select"><legend>Optional: exclude selected successful sends</legend><p className="muted">This is an explicit comparison choice, not a permanent suppression.</p>{historyItems.length ? historyItems.map(item => <label key={item.id} className="check-row"><input type="checkbox" checked={history.includes(item.id)} onChange={event => setHistory(current => event.target.checked ? [...current, item.id] : current.filter(id => id !== item.id))} /> <span>{item.name}<small>{item.accepted || 0} accepted submissions · {item.status}</small></span></label>) : <Empty text="No sending history is available yet." />}</fieldset></section>{result && <section className="panel"><div className="panel-head"><div><h3>Comparison result</h3><p className="muted">{result.counts.result} addresses · {result.counts.main_duplicates} duplicates in the main input · {result.counts.main_invalid} invalid records separated</p></div><div className="button-row"><button onClick={download}>Export CSV</button>{result.results?.length > 0 && <button className="primary" onClick={sendResult}>Send this result</button>}</div></div><div className="stat-grid"><Stat label="Result" value={result.counts.result} tone="teal" /><Stat label="Main unique" value={result.counts.main_unique} /><Stat label="Reference unique" value={result.counts.reference_unique} /></div>{result.results?.length ? <div className="table-panel"><table><thead><tr><th>Email</th><th>Classification</th><th>Source</th></tr></thead><tbody>{result.results.slice(0, 500).map((item: ApiRecord) => <tr key={item.email}><td>{item.email}</td><td>{item.classification}</td><td>{item.source}</td></tr>)}</tbody></table>{result.results.length > 500 && <p className="muted">Showing the first 500 rows; use Export CSV for the complete result.</p>}</div> : <Empty text="No addresses match this comparison." />}</section>}</div>
}

function Sender({ onRun }: { data: ApiRecord, onRun: Action }) {
  const [recipients, setRecipients] = useState(() => new URLSearchParams(window.location.search).get('list_id') ? ' ' : ''); const [file, setFile] = useState<File | null>(null); const [sender, setSender] = useState('sender@example.com'); const [subject, setSubject] = useState('A local Mailforge message'); const [text, setText] = useState('Hello {{ email }}'); const [html, setHtml] = useState(''); const [htmlFile, setHtmlFile] = useState<File | null>(null); const [assetZip, setAssetZip] = useState<File | null>(null); const [attachments, setAttachments] = useState<File[]>([]); const [label, setLabel] = useState(''); const [account, setAccount] = useState(''); const [accounts, setAccounts] = useState<ApiRecord[]>([]); const [handoffList, setHandoffList] = useState<ApiRecord | null>(null); const [campaign, setCampaignRaw] = useState<ApiRecord | null>(null); const [preview, setPreview] = useState<ApiRecord | null>(null); const [revisionId, setRevisionId] = useState(''); const [testRecipient, setTestRecipient] = useState(''); const [testResult, setTestResult] = useState<ApiRecord | null>(null); const [scheduleMode, setScheduleMode] = useState('immediate'); const [scheduledAt, setScheduledAt] = useState('')
  const setCampaign = (workspace: ApiRecord | null) => setCampaignRaw(workspace ? { ...workspace, attempts: (workspace.attempts || workspace.preview || []).map((item: ApiRecord) => ({ ...item, outcome: item.outcome || item.latest_outcome, attempt_state: item.attempt_state || item.state, transport_phase: item.transport_phase || item.latest_attempt?.transport_phase })), report: { ...(workspace.report || {}), total: workspace.report?.total ?? workspace.progress?.total ?? 0, counts: workspace.report?.counts || workspace.progress?.counts || {} } } : null)
  const handoffListId = new URLSearchParams(window.location.search).get('list_id') || ''
  useEffect(() => { void api<ApiRecord>('/providers').then(value => setAccounts(value.items || [])); if (handoffListId) void api<ApiRecord>('/lists').then(value => { const selected = (value.items || []).find((item: ApiRecord) => item.id === handoffListId) || null; setHandoffList(selected); if (selected) setRecipients('\u200b') }) }, [handoffListId])
  useEffect(() => { if (!campaign?.campaign?.id) return; const timer = window.setInterval(() => void api<ApiRecord>(`/campaigns/${campaign.campaign.id}/workspace`).then(setCampaign), 1000); return () => window.clearInterval(timer) }, [campaign?.campaign?.id])
  const create = () => onRun(async () => {
    const source = file || new File([recipients], 'pasted-recipients.txt', { type: 'text/plain' }); let list = handoffList || (handoffListId ? { id: handoffListId } : null)
    if (!list) { const checked = await upload('/imports/preview', source); if (!checked.accepted) throw new Error('No valid email addresses were found'); list = await api<ApiRecord>('/lists', { method: 'POST', body: JSON.stringify({ name: `send-${Date.now()}`, description: 'Internal recipient set created by Send' }) }); await upload(`/imports?list_id=${encodeURIComponent(list.id)}`, source) }
    const attachmentRefs: ApiRecord[] = []; for (const item of attachments) { const asset = await uploadAsset(item, 'attachment'); attachmentRefs.push({ asset_id: asset.id }) }
    let message: ApiRecord
    if (htmlFile) { message = await uploadFiles('/message-studio/custom-html/import', { html_file: htmlFile, ...(assetZip ? { assets_zip: assetZip } : {}) }, { name: subject || 'Mailforge HTML message', kind: 'message' }); const document = { ...(message.draft?.document || {}), name: subject || message.draft?.document?.name, subject, attachments: attachmentRefs }; message = await api<ApiRecord>(`/message-studio/documents/${message.id}/save`, { method: 'POST', body: JSON.stringify({ document, expected_revision_id: message.draft?.id }) }) }
    else { const baseDocument = { version: 1, name: subject, subject, preheader: '', fallbacks: {}, attachments: attachmentRefs }; const document = html.trim() ? { ...baseDocument, composition_mode: 'custom_html', custom_html: { original_source: html.trim(), asset_manifest: [] }, blocks: [{ type: 'text', text: text || 'Message' }] } : { ...baseDocument, blocks: [{ type: 'text', text }] }; message = await api<ApiRecord>('/message-studio/documents', { method: 'POST', body: JSON.stringify({ name: subject || 'Mailforge message', kind: 'message', document }) }) }
    const published = await api<ApiRecord>(`/message-studio/documents/${message.id}/publish`, { method: 'POST', body: JSON.stringify({}) }); const publishedRevision = published.current_published_revision_id || message.current_published_revision_id; setRevisionId(publishedRevision)
    const created = await api<ApiRecord>('/campaigns', { method: 'POST', body: JSON.stringify({ name: label.trim() || `Send · ${subject} · ${Date.now()}`, list_id: list.id, message_revision_id: publishedRevision, provider_account_ref: account || null, sender_email: sender, subject, text }) }); const workspace = await api<ApiRecord>(`/campaigns/${created.id}/workspace`); setCampaign(workspace); return workspace
  }, 'Recipient set and message prepared')
  const action = (path: string, message: string) => campaign?.campaign?.id && onRun(async () => { if (path === '/prepare') { const prepared = await api<ApiRecord>(`/campaigns/${campaign.campaign.id}/prepare`, { method: 'POST', body: JSON.stringify({}) }); setPreview(prepared) } else if (path === '/preview') { const contact = campaign.preview?.[0]?.contact_id; setPreview(await api<ApiRecord>('/message-studio/preview', { method: 'POST', body: JSON.stringify({ revision_id: revisionId || campaign.campaign.message_revision_id, contact_id: contact || null }) })) } else if (path === '/schedule') { await api(`/campaigns/${campaign.campaign.id}/schedule`, { method: 'PUT', body: JSON.stringify({ mode: 'at', timezone: 'UTC', scheduled_at: new Date(scheduledAt).toISOString(), weekdays: [0, 1, 2, 3, 4, 5, 6] }) }) } else { const executionPath = path === '/simulate' && account ? (campaign.campaign.configuration?.execution_mode === 'external_smtp' ? '/execute-external' : '/execute') : path; const options = executionPath === '/execute' ? { method: 'POST', body: JSON.stringify({ mode: 'loopback_smtp' }) } : { method: 'POST' }; await api(`/campaigns/${campaign.campaign.id}${executionPath}`, options) }; const next = await api<ApiRecord>(`/campaigns/${campaign.campaign.id}/workspace`); setCampaign(next); return next }, message)
  const sendTest = () => onRun(async () => { if (!account || !revisionId || !testRecipient.trim()) throw new Error('Choose an account, publish the message, and enter one test recipient'); const purpose = accounts.find(item => item.ref === account)?.sandbox_state === 'active' ? 'sandbox_qualification' : 'controlled_test_send'; const proof = await api<ApiRecord>(`/providers/${encodeURIComponent(account)}/test-proof`, { method: 'POST', body: JSON.stringify({ sender, recipient: testRecipient.trim(), message_revision_id: revisionId }) }); const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString(); const grant = await api<ApiRecord>(`/providers/${encodeURIComponent(account)}/grants`, { method: 'POST', body: JSON.stringify({ purpose, sender, recipient: testRecipient.trim(), expires_at: expiresAt, proof_hash: proof.proof_hash }) }); const result = await api<ApiRecord>(`/providers/${encodeURIComponent(account)}/test-send`, { method: 'POST', body: JSON.stringify({ sender, recipient: testRecipient.trim(), message: null, idempotency_key: `ui-test-${Date.now()}`, authorization_ref: grant.authorization_ref, purpose: grant.purpose, expires_at: expiresAt, message_revision_id: revisionId, proof_id: proof.proof_id, proof_hash: proof.proof_hash }) }); setTestResult(result); return result }, 'Distinct one-recipient test operation completed')
  const state = campaign?.campaign?.status || 'draft'; const report = campaign?.report || campaign?.campaign?.report || {}
  return <div className="content"><PageIntro eyebrow="EMAIL SENDER" title="Prepare one clear send" text="Use pasted addresses, a supported file, or an existing local list result. Add HTML, embedded assets, attachments, and personalization before reviewing the exact operation." badge="Simulation first" />{!campaign && <><section className="panel"><div className="panel-head"><div><h3>Recipients</h3><p className="muted">Addresses only are enough. Names are preserved from structured files for personalization.</p></div></div><label>Paste addresses<textarea rows={5} value={recipients} onChange={event => setRecipients(event.target.value)} placeholder="one@example.com\ntwo@example.com" /></label><label className="file-drop">{file ? file.name : 'Or choose a recipient file'}<input aria-label="Recipient file" type="file" accept=".txt,.csv,.json,.jsonl" onChange={event => setFile(event.target.files?.[0] || null)} /></label></section><section className="split"><section className="panel"><h3>Message</h3><label>Sender email<input value={sender} onChange={event => setSender(event.target.value)} /></label><label>Subject<input value={subject} onChange={event => setSubject(event.target.value)} /></label><label>Plain-text message<textarea rows={6} value={text} onChange={event => setText(event.target.value)} /></label><label>HTML message <span className="muted">(optional)</span><textarea rows={8} value={html} onChange={event => setHtml(event.target.value)} placeholder="Paste existing HTML here" /></label><label className="file-drop">{htmlFile ? htmlFile.name : 'Or import an HTML file'}<input aria-label="HTML source file" type="file" accept=".html,.htm" onChange={event => setHtmlFile(event.target.files?.[0] || null)} /></label><label className="file-drop">{assetZip ? assetZip.name : 'Optional image/CSS asset bundle (.zip)'}<input aria-label="HTML asset bundle" type="file" accept=".zip" onChange={event => setAssetZip(event.target.files?.[0] || null)} /></label><label className="file-drop">{attachments.length ? `${attachments.length} attachment${attachments.length === 1 ? '' : 's'} selected` : 'Add file attachments'}<input aria-label="Message attachments" type="file" multiple onChange={event => setAttachments(Array.from(event.target.files || []))} /></label></section><section className="panel"><h3>Sending options</h3><label>Label <span className="muted">(optional)</span><input value={label} onChange={event => setLabel(event.target.value)} placeholder="For example: investor introductions" /></label><label>Email account<select value={account} onChange={event => setAccount(event.target.value)}><option value="">Choose when ready</option>{accounts.map(item => <option key={item.ref} value={item.ref}>{item.display_name || item.ref} · {item.sender_email || 'no sender'}</option>)}</select></label><label>Timing<select value={scheduleMode} onChange={event => setScheduleMode(event.target.value)}><option value="immediate">Start after review</option><option value="scheduled">Schedule for later</option></select></label>{scheduleMode === 'scheduled' && <label>Start at<input type="datetime-local" value={scheduledAt} onChange={event => setScheduledAt(event.target.value)} /></label>}<button className="primary full" disabled={(!recipients.trim() && !file) || !subject.trim() || !sender.trim()} onClick={create}>Review this send</button></section></section></>}{campaign && <><section className="panel send-review"><div className="panel-head"><div><h3>{campaign.campaign?.name || 'Send review'}</h3><p className="muted">{campaign.recipients?.length || campaign.audience?.total || 'Selected'} recipients · status {state}</p></div><span className={`status ${state}`}>{state}</span></div><div className="stat-grid"><Stat label="Eligible" value={campaign.recipients?.filter((item: ApiRecord) => item.status === 'eligible').length ?? report.total ?? 0} tone="teal" /><Stat label="Accepted" value={report.counts?.accepted ?? 0} /><Stat label="Uncertain" value={report.counts?.ambiguous ?? 0} tone="amber" /></div><div className="button-row">{state === 'draft' && <button className="primary" onClick={() => action('/prepare', 'Send prepared; inspect the exact scope before authorizing')}>Prepare exact scope</button>}{['ready', 'prepared'].includes(state) && <button className="primary" onClick={() => action('/authorize', 'Local simulation authorized')}>Authorize local simulation</button>}{['authorized', 'ready'].includes(state) && <button onClick={() => action('/simulate', account && campaign.campaign.configuration?.execution_mode === 'external_smtp' ? 'Approved external operation started' : 'Controlled local send started')}>{campaign.campaign.configuration?.execution_mode === 'external_smtp' ? 'Start approved external send' : 'Start local send'}</button>}{state === 'ready' && scheduleMode === 'scheduled' && <button onClick={() => action('/schedule', 'Send scheduled locally')}>Schedule send</button>}{['running', 'scheduled'].includes(state) && <button onClick={() => action('/pause', 'Send paused')}>Pause</button>}{state === 'paused' && <button onClick={() => action('/resume', 'Send resumed')}>Resume</button>}<button onClick={() => { setCampaign(null); setPreview(null); setTestResult(null) }}>Start another send</button></div><div className="button-row"><button onClick={() => action('/preview', 'Personalized message preview ready')}>Preview personalized message</button></div>{preview?.html && <div className="preview-box"><strong>Rendered preview</strong><span>{preview.subject} · {preview.attachments?.length || 0} attachment(s)</span><iframe title="Personalized message preview" srcDoc={preview.html} sandbox="allow-same-origin" /></div>}{campaign.message_previews?.[0]?.html && <div className="preview-box"><strong>Prepared recipient preview</strong><span>{campaign.message_previews[0].subject} · {campaign.message_previews[0].attachments?.length || 0} attachment(s)</span><iframe title="Prepared recipient message preview" srcDoc={campaign.message_previews[0].html} sandbox="allow-same-origin" /></div>}{testResult && <div className="preview-box"><strong>Test operation result</strong><span>{testResult.status || testResult.outcome || 'recorded'} · one recipient only</span></div>}{campaign.attempts?.length ? <div className="table-panel"><table><thead><tr><th>Recipient</th><th>Outcome</th><th>Phase</th></tr></thead><tbody>{campaign.attempts.map((item: ApiRecord) => <tr key={item.id}><td>{item.recipient || item.email}</td><td>{item.outcome || item.attempt_state}</td><td>{item.transport_phase || 'not started'}</td></tr>)}</tbody></table></div> : <p className="muted">The exact recipient scope and message checks appear after preparation.</p>}</section><section className="panel"><h3>Send one controlled test</h3><p className="muted">This is a separate, explicitly scoped one-recipient operation. It never starts the prepared audience send.</p><label>Test recipient<input value={testRecipient} onChange={event => setTestRecipient(event.target.value)} placeholder="test@example.com" /></label><button onClick={sendTest} disabled={!account || !revisionId || !testRecipient.trim()}>Send distinct test email</button></section><ExternalAuthorizationPanel campaignId={campaign.campaign.id} onRun={onRun} onAuthorized={async () => { const next = await api<ApiRecord>(`/campaigns/${campaign.campaign.id}/workspace`); setCampaign(next) }} /></>}
  </div>
}

function ExternalAuthorizationPanel({ campaignId, onRun, onAuthorized }: { campaignId: string, onRun: Action, onAuthorized: () => Promise<void> }) {
  const [preview, setPreview] = useState<ApiRecord | null>(null); const [purpose, setPurpose] = useState('Controlled external authorization qualification'); const [expiresAt, setExpiresAt] = useState(''); const [confirmed, setConfirmed] = useState(false); const [prepared, setPrepared] = useState<ApiRecord | null>(null)
  const review = () => onRun(async () => { const result = await api<ApiRecord>(`/campaigns/${campaignId}/external-authorization-preview`); setPreview(result); return result }, 'External scope reviewed; no provider connection was made')
  const prepare = () => preview && onRun(async () => { const result = await api<ApiRecord>(`/campaigns/${campaignId}/prepare-external-authorization`, { method: 'POST', body: JSON.stringify({ purpose, expires_at: new Date(expiresAt).toISOString(), max_submissions: preview.max_submissions, prepared_set_hash: preview.prepared_set_hash, confirm_exact_scope: confirmed }) }); setPrepared(result); await onAuthorized(); return result }, 'Server authorization prepared; external execution remains separately gated')
  return <details className="panel external-auth"><summary>Use an external sending account</summary><p className="muted">This boundary is qualification-only. It shows the exact provider, recipients, expiry, and submission budget before any external action; no external connection is made here.</p>{!preview && <button onClick={review}>Review external scope</button>}{preview && <><div className="scope-summary"><strong>{preview.provider?.ref}</strong><span>{preview.recipients?.length} recipients · maximum {preview.max_submissions} submissions</span><span>{preview.provider?.host}:{preview.provider?.port} · external access disabled by default</span></div><label>Purpose<input value={purpose} onChange={event => setPurpose(event.target.value)} /></label><label>Authorization expiry<input type="datetime-local" value={expiresAt} onChange={event => setExpiresAt(event.target.value)} /></label><label className="check-row"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /> I confirm this exact prepared recipient and submission scope.</label><button className="primary" disabled={!confirmed || !expiresAt || !purpose.trim()} onClick={prepare}>Prepare scoped authorization</button></>}{prepared && <div className="preview-box"><strong>Authorization prepared</strong><span>{prepared.scope?.recipients} recipients · {prepared.scope?.max_submissions} submissions · execution is still separately controlled</span></div>}</details>
}

function History({ data, onNavigate }: { data: ApiRecord, onNavigate: Navigate }) { const items: ApiRecord[] = data.items || data.campaigns || []; return <div className="content"><PageIntro eyebrow="SENDING HISTORY" title="See what happened" text="History distinguishes preparation, provider acceptance, deferred work, cancellation, and uncertain outcomes. It never claims inbox delivery." badge={`${items.length} shown`} /><section className="panel table-panel">{items.length ? <table><thead><tr><th>Operation</th><th>State</th><th>Accepted</th><th>Updated</th></tr></thead><tbody>{items.map(item => <tr key={item.id} onClick={() => onNavigate('send')}><td><strong>{item.name}</strong><small className="table-subline">{item.configuration?.sender_email || item.sender_email || 'sender not shown'}</small></td><td><span className={`status ${item.status}`}>{item.status}</span></td><td>{item.report?.counts?.accepted ?? item.accepted ?? 0}</td><td>{new Date(item.updated_at || item.created_at).toLocaleString()}</td></tr>)}</tbody></table> : <Empty text="No sending operations yet. They will appear here after you prepare one." />}</section><button className="primary" onClick={() => onNavigate('send')}>Prepare a send</button></div> }

function Accounts({ data, onRun }: { data: ApiRecord, onRun: Action }) { const [ref, setRef] = useState('smtp-account'); const [display, setDisplay] = useState('My email account'); const [sender, setSender] = useState('sender@example.com'); const [host, setHost] = useState('127.0.0.1'); const [port, setPort] = useState('587'); const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [tls, setTls] = useState('starttls'); const accounts: ApiRecord[] = data.items || []; const save = () => onRun(async () => { const result = await api<ApiRecord>('/providers', { method: 'POST', body: JSON.stringify({ ref, display_name: display, sender_email: sender, kind: 'smtp', host, port: Number(port), username, credential_ref: `keychain:${ref}`, tls_mode: tls, auth_method: 'password', pacing_per_minute: 60, max_concurrency: 1 }) }); if (password) await api('/providers/credentials', { method: 'POST', body: JSON.stringify({ provider_ref: ref, credential_ref: `keychain:${ref}`, secret: password }) }); setPassword(''); return result }, 'Email account saved locally; the password was not returned'); return <div className="content"><PageIntro eyebrow="EMAIL ACCOUNTS" title="Connect an account only when you need to send" text="Credentials are stored through the local credential boundary. Mailforge never displays the password after saving and never synchronizes this account." badge="SMTP only" /><div className="split"><section className="panel"><h3>Account details</h3><label>Account name<input value={display} onChange={event => setDisplay(event.target.value)} /></label><label>Sender email<input value={sender} onChange={event => setSender(event.target.value)} /></label><label>SMTP server<input value={host} onChange={event => setHost(event.target.value)} /></label><div className="form-pair"><label>Port<input inputMode="numeric" value={port} onChange={event => setPort(event.target.value)} /></label><label>Encryption<select value={tls} onChange={event => setTls(event.target.value)}><option value="starttls">STARTTLS</option><option value="implicit_tls">TLS</option></select></label></div><label>Username<input value={username} onChange={event => setUsername(event.target.value)} /></label><label>Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} autoComplete="new-password" /></label><details className="advanced-settings"><summary>Advanced account reference</summary><label>Local reference<input value={ref} onChange={event => setRef(event.target.value)} /></label><p className="muted">This reference is used to bind a send. It is not a credential.</p></details><button className="primary full" onClick={save}>Save account</button></section><section className="panel"><h3>Saved accounts</h3>{accounts.length ? <div className="list-stack">{accounts.map(item => <div className="list-row" key={item.ref}><span><strong>{item.display_name || item.ref}</strong><small>{item.sender_email || 'no sender'} · {item.host}:{item.port} · {item.status}</small></span><span className="tag">{item.outbound_enabled ? 'ready' : 'check settings'}</span></div>)}</div> : <Empty text="No email accounts yet. Sorting and comparison work without one." />}</section></div></div> }

function SavedLists({ data, onNavigate }: { data: ApiRecord, onNavigate: Navigate }) { const items: ApiRecord[] = data.items || []; return <div className="content"><PageIntro eyebrow="SAVED LISTS" title="Keep useful lists close at hand" text="Saved lists are optional conveniences. Sorting, comparison, and sending remain useful without building a database first." badge={`${items.length} saved`} /><section className="panel table-panel">{items.length ? <table><thead><tr><th>Name</th><th>Addresses</th><th>Created</th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td><strong>{item.name}</strong><small className="table-subline">{item.description}</small></td><td>{item.contact_count ?? item.count ?? '—'}</td><td>{item.created_at ? new Date(item.created_at).toLocaleDateString() : '—'}</td></tr>)}</tbody></table> : <Empty text="No saved lists yet. You can send directly from a file or paste addresses." />}</section><button className="primary" onClick={() => onNavigate('send')}>Send from a list or file</button></div> }
function Settings({ data }: { data: ApiRecord }) { return <div className="content"><PageIntro eyebrow="SETTINGS" title="Local storage and recovery" text="Keep advanced operational details available without making them part of everyday list work." badge="Local only" /><section className="split"><section className="panel"><h3>Workspace</h3><div className="metric-list"><div><dt>Application version</dt><dd>{data.version || 'Mailforge'}</dd></div><div><dt>Storage</dt><dd>Local SQLite</dd></div><div><dt>Network mode</dt><dd>Loopback interface</dd></div><div><dt>Delivery claim</dt><dd>Provider acceptance only</dd></div></div></section><section className="panel"><h3>Recovery</h3><p className="muted">Backups and integrity checks remain available here for operators who need them. They do not affect sorting or comparison.</p><p className="muted">Private message bodies, credentials, and runtime paths are not shown in ordinary diagnostics.</p></section></section></div> }

export default App
